<?php
namespace App\Http\Requests\PublicChrome;
use App\Domain\PublicChrome\PublicLink; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Validator;
class FooterRequest extends FormRequest { public function authorize():bool{return true;} protected function prepareForValidation():void{$this->merge(['show_newsletter'=>false,'show_contact_details'=>$this->boolean('show_contact_details'),'show_social_links'=>$this->boolean('show_social_links'),'show_legal_links'=>$this->boolean('show_legal_links')]);} public function rules():array{return ['short_description'=>['nullable','string','max:500'],'show_contact_details'=>['boolean'],'show_social_links'=>['boolean'],'show_newsletter'=>['accepted:false'],'copyright_text'=>['nullable','string','max:240'],'developed_by_text'=>['required','string','max:160'],'developed_by_url'=>['nullable','string','max:2048'],'show_legal_links'=>['boolean']];} public function after():array{return [function(Validator $v){if($this->filled('developed_by_url')&&!PublicLink::isSafeUrl($this->input('developed_by_url')))$v->errors()->add('developed_by_url','Use a safe URL.');if(!str_contains((string)$this->input('developed_by_text'),'Naxas Innovations Limited'))$v->errors()->add('developed_by_text','Product attribution must name Naxas Innovations Limited.');}];} }
